mapper.select:
SELECT id, sale_record_id, refund_amount, cancelled_at, reason, created_at
FROM cancel_record
WHERE id = #{id}

SELECT COALESCE(SUM(refund_amount), 0)
FROM cancel_record
WHERE sale_record_id = #{saleRecordId}

SELECT
    COALESCE(SUM(cr.refund_amount), 0) AS total_amount,
    COUNT(*) AS count
FROM cancel_record cr
    JOIN sale_record s ON cr.sale_record_id = s.id
    JOIN course c ON s.course_id = c.id
WHERE c.creator_id = #{creatorId}
  AND cr.cancelled_at >= #{startAt}
  AND cr.cancelled_at < #{endAtExclusive}
